def get_number_bounds(schema: Schema) -> Tuple[Optional[float], Optional[float], bool, bool]:
    """Get the min and max allowed floats, and whether they are exclusive."""
    lower, upper, exmin, exmax = _get_numeric_bounds(schema)
    if lower is not None:
        lo = float(lower)
        if lo < lower:
            lo = next_up(lo)
            exmin = False
        lower = lo
    if upper is not None:
        hi = float(upper)
        if hi > upper:
            hi = next_down(hi)
            exmax = False
        upper = hi
    return (lower, upper, exmin, exmax)

def merged_as_strategies(schemas: List[Schema], *, alphabet: CharStrategy, custom_formats: Optional[Dict[str, st.SearchStrategy[str]]]) -> st.SearchStrategy[JSONType]:
    assert schemas, 'internal error: must pass at least one schema to merge'
    if len(schemas) == 1:
        return __from_schema(schemas[0], alphabet=alphabet, custom_formats=custom_formats)
    strats = []
    combined: Set[str] = set()
    inputs = {encode_canonical_json(s): s for s in schemas}
    for group in itertools.chain.from_iterable((itertools.combinations(inputs, n) for n in range(len(inputs), 0, -1))):
        if combined.issuperset(group):
            continue
        s = merged([inputs[g] for g in group])
        if s is not None and s != FALSEY:
            strats.append(__from_schema(s, alphabet=alphabet, custom_formats=custom_formats).filter(lambda obj, validators=tuple((make_validator(s).is_valid for s in schemas)): all((v(obj) for v in validators))))
            combined.update(group)
    return st.one_of(strats)

