    if not type_:
        assert type_ == []
        return FALSEY
    if type_ == ['null']:
        return {'const': None}
    if type_ == ['boolean']:
        return {'enum': [False, True]}
    if type_ == ['null', 'boolean']:
        return {'enum': [None, False, True]}
    if len(type_) == 1:
        schema['type'] = type_[0]
    elif type_ == get_type({}):
