        lower = lo
    if upper is not None:
        hi = math.floor(upper)
        if exmax and hi == upper:
            hi -= 1
        upper = hi
    return (lower, upper)

@st.composite
def gen_object(draw: Any) -> Schema:
    """Draw an object schema."""
    out: Schema = {'type': 'object'}
    names = draw(st.sampled_from([None, None, None, draw(gen_string())]))
    name_strat = st.text() if names is None else from_schema(names)
    required = draw(st.just(False) | st.lists(name_strat, min_size=1, max_size=5, unique=True))
    properties = draw(st.dictionaries(name_strat, _json_schemata(recur=False)))
    disjoint = REGEX_PATTERNS.filter(lambda r: all((re.search(r, string=name) is None for name in properties)))
    patterns = draw(st.dictionaries(disjoint, _json_schemata(recur=False), max_size=1))
    additional = draw(st.none() | _json_schemata(recur=False))
    min_size = draw(st.none() | st.integers(0, 5))
    max_size = draw(st.none() | st.integers(2, 5))
    if min_size is not None and max_size is not None and (min_size > max_size):
        min_size, max_size = (max_size, min_size)
    if names is not None:
        out['propertyNames'] = names
    if required:
        out['required'] = required
        if min_size is not None:
            min_size += len(required)
        if max_size is not None:
            max_size += len(required)
    if min_size is not None:
        out['minProperties'] = min_size
    if max_size is not None:
        out['maxProperties'] = max_size
    if properties:
        out['properties'] = properties
        props = st.sampled_from(sorted(properties))
        if draw(st.integers(0, 3)) == 3:
            out['dependencies'] = draw(st.dictionaries(props, st.lists(props, unique=True)))
        elif draw(st.integers(0, 3)) == 3:
            out['dependencies'] = draw(st.dictionaries(props, json_schemata()))
    if patterns:
        out['patternProperties'] = patterns
    if additional is not None:
        out['additionalProperties'] = additional
    return out

def json_schemata() -> st.SearchStrategy[Union[bool, Schema]]:
    """Return a Hypothesis strategy for arbitrary JSON schemata.

    This strategy may generate anything that can be handled by `from_schema`,
    and is used to provide full branch coverage when testing this package.
    """
    return _json_schemata()

def __from_schema(schema: Union[bool, Schema], *, alphabet: CharStrategy, custom_formats: Optional[Dict[str, st.SearchStrategy[str]]]) -> st.SearchStrategy[JSONType]:
    try:
        schema = resolve_all_refs(schema)
    except RecursionError:
        raise HypothesisRefResolutionError(f'Could not resolve recursive references in schema={schema!r}') from None
    if custom_formats is not None and _FORMATS_TOKEN not in custom_formats:
        assert isinstance(custom_formats, dict)
        for name, strat in custom_formats.items():
            if not isinstance(name, str):
                raise InvalidArgument(f'format name {name!r} must be a string')
            if not isinstance(strat, st.SearchStrategy):
                raise InvalidArgument(f'custom_formats[{name!r}]={strat!r} must be a Hypothesis strategy which generates strings matching this format.')
            if name in STRING_FORMATS:
                warnings.warn(f'Overriding standard format {name!r} - was {STRING_FORMATS[name]!r}, now {strat!r}', HypothesisWarning, stacklevel=2)
        format_checker = jsonschema.FormatChecker()
        custom_formats = {name: _get_format_filter(name, format_checker, strategy) for name, strategy in custom_formats.items()}
        custom_formats[_FORMATS_TOKEN] = None
    schema = canonicalish(schema)
    if schema == FALSEY:
        return st.nothing()
    if schema == TRUTHY:
        return JSON_STRATEGY
    assert isinstance(schema, dict)
    if schema.get('$schema') == 'http://json-schema.org/draft-03/schema#':
        raise InvalidArgument('Draft-03 schemas are not supported')
    if '$schema' in schema:
        jsonschema.validators.validator_for(schema).check_schema(schema)
    if 'not' in schema:
        not_ = schema.pop('not')
        assert isinstance(not_, dict)
        validator = make_validator(not_).is_valid
        return __from_schema(schema, alphabet=alphabet, custom_formats=custom_formats).filter(lambda v: not validator(v))
    if 'anyOf' in schema:
        tmp = schema.copy()
        ao = tmp.pop('anyOf')
        assert isinstance(ao, list)
        return st.one_of([merged_as_strategies([tmp, s], alphabet=alphabet, custom_formats=custom_formats) for s in ao])
    if 'allOf' in schema:
        tmp = schema.copy()
        ao = tmp.pop('allOf')
        assert isinstance(ao, list)
        return merged_as_strategies([tmp, *ao], alphabet=alphabet, custom_formats=custom_formats)
    if 'oneOf' in schema:
        tmp = schema.copy()
        oo = tmp.pop('oneOf')
        assert isinstance(oo, list)
        schemas = [merged([tmp, s]) for s in oo]
        return st.one_of([__from_schema(s, alphabet=alphabet, custom_formats=custom_formats) for s in schemas if s is not None]).filter(make_validator(schema).is_valid)
    if 'enum' in schema:
        assert schema['enum'], 'Canonicalises to non-empty list or FALSEY'
        return st.sampled_from(schema['enum'])
    if 'const' in schema:
        return st.just(schema['const'])
    map_: Dict[str, Callable[[Schema], st.SearchStrategy[JSONType]]] = {'null': lambda _: st.none(), 'boolean': lambda _: st.booleans(), 'number': number_schema, 'integer': integer_schema, 'string': partial(string_schema, custom_formats, alphabet), 'array': partial(array_schema, custom_formats, alphabet), 'object': partial(object_schema, custom_formats, alphabet)}
    assert set(map_) == set(TYPE_STRINGS)
    return st.one_of([map_[t](schema) for t in get_type(schema)])

def gen_enum() -> st.SearchStrategy[Dict[str, List[JSONType]]]:
    """Return a strategy for enum schema."""
    return st.fixed_dictionaries({'enum': st.lists(JSON_STRATEGY, min_size=1, max_size=10, unique_by=encode_canonical_json)})

def resolve_all_refs(schema: Union[bool, Schema], *, resolver: Optional[LocalResolver]=None) -> Schema:
    """
    Resolve all references in the given schema.

    This handles nested definitions, but not recursive definitions.
    The latter require special handling to convert to strategies and are much
    less common, so we just ignore them (and error out) for now.
    """
    if isinstance(schema, bool):
        return canonicalish(schema)
    assert isinstance(schema, dict), schema
    if resolver is None:
        resolver = LocalResolver.from_schema(deepcopy(schema))
    if not isinstance(resolver, _RefResolver):
        raise InvalidArgument(f'resolver={resolver} (type {type(resolver).__name__}) is not a RefResolver')
    if '$ref' in schema:
        s = dict(schema)
        ref = s.pop('$ref')
        with resolver.resolving(ref) as got:
            m = merged([s, resolve_all_refs(got, resolver=resolver)])
            if m is None:
                msg = f'$ref:{ref!r} had incompatible base schema {s!r}'
                raise HypothesisRefResolutionError(msg)
            assert '$ref' not in m
            return m
    assert '$ref' not in schema
    for key in SCHEMA_KEYS:
        val = schema.get(key, False)
        if isinstance(val, list):
            schema[key] = [resolve_all_refs(v, resolver=resolver) if isinstance(v, dict) else v for v in val]
        elif isinstance(val, dict):
            schema[key] = resolve_all_refs(val, resolver=resolver)
        else:
            assert isinstance(val, bool)
    for key in SCHEMA_OBJECT_KEYS:
        if key in schema:
            subschema = schema[key]
            assert isinstance(subschema, dict)
            schema[key] = {k: resolve_all_refs(v, resolver=resolver) if isinstance(v, dict) else v for k, v in subschema.items()}
    assert isinstance(schema, dict)
    assert '$ref' not in schema
    return schema

def upper_bound_instances(schema: Schema) -> float:
    """Return an upper bound on the number of instances that match this schema."""
    if schema == FALSEY:
        return 0
    if 'const' in schema:
        return 1
    if 'enum' in schema:
        assert isinstance(schema['enum'], list)
        return len(schema['enum'])
    if get_type(schema) == ['integer']:
        lower, upper = get_integer_bounds(schema)
        if lower is not None and upper is not None:
            mul = schema.get('multipleOf')
            if isinstance(mul, int):
                return 1 + (upper - lower) % mul
            return 1 + (upper - lower)
    if get_type(schema) == ['array'] and isinstance(schema.get('items'), dict) and (schema.get('maxItems', math.inf) < 100):
        items_bound = upper_bound_instances(schema['items'])
        if items_bound < 100:
            lo, hi = (schema.get('minItems', 0), schema['maxItems'])
            assert isinstance(lo, int)
            assert isinstance(hi, int)
            return sum((items_bound ** n for n in range(lo, hi + 1)))
    return math.inf

def _get_numeric_bounds(schema: Schema) -> Tuple[Optional[float], Optional[float], bool, bool]:
    """Get the min and max allowed numbers, and whether they are exclusive."""
    lower = schema.get('minimum')
    upper = schema.get('maximum')
    exmin = schema.get('exclusiveMinimum', False)
    exmax = schema.get('exclusiveMaximum', False)
    assert lower is None or isinstance(lower, (int, float))
    assert upper is None or isinstance(upper, (int, float))
    assert isinstance(exmin, (bool, int, float))
    assert isinstance(exmax, (bool, int, float))
    if exmin is not True and exmin is not False:
        if lower is None or exmin >= lower:
            lower, exmin = (exmin, True)
        else:
            exmin = False
    if exmax is not True and exmax is not False:
        if upper is None or exmax <= upper:
            upper, exmax = (exmax, True)
        else:
            exmax = False
    assert isinstance(exmin, bool)
    assert isinstance(exmax, bool)
    return (lower, upper, exmin, exmax)

@st.composite
def gen_string(draw: Any) -> Dict[str, Union[str, int]]:
    """Draw a string schema."""
    min_size = draw(st.none() | st.integers(0, 10))
    max_size = draw(st.none() | st.integers(0, 1000))
    if min_size is not None and max_size is not None and (min_size > max_size):
        min_size, max_size = (max_size, min_size)
    pattern = draw(st.none() | REGEX_PATTERNS)
    format_ = draw(st.none() | st.sampled_from(sorted(STRING_FORMATS)))
    out: Dict[str, Union[str, int]] = {'type': 'string'}
    if pattern is not None:
        out['pattern'] = pattern
    elif format_ is not None:
        out['format'] = format_
    if min_size is not None:
        out['minLength'] = min_size
    if max_size is not None:
        out['maxLength'] = max_size
    return out

@st.composite
def gen_number(draw: Any, kind: str) -> Dict[str, Union[str, float]]:
    """Draw a numeric schema."""
    max_int_float = 2 ** 53
    lower = draw(st.none() | st.integers(-max_int_float, max_int_float))
    upper = draw(st.none() | st.integers(-max_int_float, max_int_float))
    if lower is not None and upper is not None and (lower > upper):
        lower, upper = (upper, lower)
    multiple_of = draw(st.none() | st.integers(2, 100) | st.floats(1 / 1024, 100, exclude_min=True))
    assume(None in (multiple_of, lower, upper) or multiple_of <= upper - lower)
    assert kind in ('integer', 'number')
    out: Dict[str, Union[str, float]] = {'type': kind}
    assert hasattr(jsonschema, 'Draft7Validator')
    if lower is not None:
        if draw(st.booleans(), label='exclusiveMinimum'):
            out['exclusiveMinimum'] = lower - 1
        else:
            out['minimum'] = lower
    if upper is not None:
        if draw(st.booleans(), label='exclusiveMaximum'):
            out['exclusiveMaximum'] = upper + 1
        else:
            out['maximum'] = upper
    if multiple_of is not None:
        out['multipleOf'] = multiple_of
    return out

def merged_as_strategies(schemas: List[Schema], *, alphabet: CharStrategy, custom_formats: Optional[Dict[str, st.SearchStrategy[str]]]) -> st.SearchStrategy[JSONType]:
    assert schemas, 'internal error: must pass at least one schema to merge'
    if len(schemas) == 1:
        return __from_schema(schemas[0], alphabet=alphabet, custom_formats=custom_formats)
    strats = []
    combined: Set[str] = set()
    inputs = {encode_canonical_json(s): s for s in schemas}
    for group in itertools.chain.from_iterable((itertools.combinations(inputs, n) for n in range(len(inputs), 0, -1))):
        if combined.issuperset(group):
            continue
        s = merged([inputs[g] for g in group])
        if s is not None and s != FALSEY:
            strats.append(__from_schema(s, alphabet=alphabet, custom_formats=custom_formats).filter(lambda obj, validators=tuple((make_validator(s).is_valid for s in schemas)): all((v(obj) for v in validators))))
            combined.update(group)
    return st.one_of(strats)

def canonicalish(schema: JSONType) -> Dict[str, Any]:
    """Convert a schema into a more-canonical form.

    This is obviously incomplete, but improves best-effort recognition of
    equivalent schemas and makes conversion logic simpler.
    """
    if schema is True:
        return {}
    elif schema is False:
        return {'not': {}}
    schema = json.loads(encode_canonical_json(schema))
    if not isinstance(schema, dict):
        raise InvalidArgument(f'Got schema={schema!r} of type {type(schema).__name__}, but expected a dict.')
    if 'const' in schema:
        if not make_validator(schema).is_valid(schema['const']):
            return FALSEY
        return {'const': schema['const']}
    if 'enum' in schema:
        validator = make_validator(schema)
        enum_ = sorted((v for v in schema['enum'] if validator.is_valid(v)), key=sort_key)
        if not enum_:
            return FALSEY
        elif len(enum_) == 1:
            return {'const': enum_[0]}
        return {'enum': enum_}
    if_ = schema.pop('if', None)
    then = schema.pop('then', schema)
    else_ = schema.pop('else', schema)
    if if_ is not None and (then is not schema or else_ is not schema) and (then not in (if_, TRUTHY) or else_ != TRUTHY):
        alternatives = [{'allOf': [if_, then, schema]}, {'allOf': [{'not': if_}, else_, schema]}]
        schema = canonicalish({'anyOf': alternatives})
    assert isinstance(schema, dict)
    for key in SCHEMA_KEYS:
        if isinstance(schema.get(key), list):
            schema[key] = [canonicalish(v) for v in schema[key]]
        elif isinstance(schema.get(key), (bool, dict)):
            schema[key] = canonicalish(schema[key])
        else:
            assert key not in schema, (key, schema[key])
    for key in SCHEMA_OBJECT_KEYS:
        if key in schema:
            schema[key] = {k: v if isinstance(v, list) else canonicalish(v) for k, v in schema[key].items()}
    if 'multipleOf' in schema:
        schema['multipleOf'] = abs(schema['multipleOf'])
    type_ = get_type(schema)
    if 'number' in type_:
        if schema.get('exclusiveMinimum') is False:
            del schema['exclusiveMinimum']
        if schema.get('exclusiveMaximum') is False:
            del schema['exclusiveMaximum']
        lo, hi, exmin, exmax = get_number_bounds(schema)
        mul = schema.get('multipleOf')
        if isinstance(mul, int):
            type_.remove('number')
            type_ = [t for t in TYPE_STRINGS if t in type_ or t == 'integer']
        elif lo is not None and hi is not None:
            lobound = next_up(lo) if exmin else lo
            hibound = next_down(hi) if exmax else hi
            if mul and (not has_divisibles(lo, hi, mul, exmin, exmax)) or lobound > hibound:
                type_.remove('number')
            elif type_ == ['number'] and lobound == hibound:
                return {'const': lobound}
    if 'integer' in type_:
        lo, hi = get_integer_bounds(schema)
        mul = schema.get('multipleOf')
        if mul is not None and 'number' not in type_ and (Fraction(mul).numerator == 1):
            schema.pop('multipleOf')
            mul = None
        if lo is not None and isinstance(mul, int) and (mul > 1) and lo % mul:
            lo += mul - lo % mul
        if hi is not None and isinstance(mul, int) and (mul > 1) and hi % mul:
            hi -= hi % mul
        if lo is not None:
            schema['minimum'] = lo
            schema.pop('exclusiveMinimum', None)
        if hi is not None:
            schema['maximum'] = hi
            schema.pop('exclusiveMaximum', None)
        if lo is not None and hi is not None and (lo > hi):
            type_.remove('integer')
        elif type_ == ['integer'] and lo == hi and make_validator(schema).is_valid(lo):
            return {'const': lo}
    if 'array' in type_ and 'contains' in schema:
        if isinstance(schema.get('items'), dict):
            contains_items = merged([schema['contains'], schema['items']])
            if contains_items is not None:
                schema['contains'] = contains_items
        if schema['contains'] == FALSEY:
            type_.remove('array')
        else:
            schema['minItems'] = max(schema.get('minItems', 0), 1)
        if schema['contains'] == TRUTHY:
            schema.pop('contains')
            schema['minItems'] = max(schema.get('minItems', 1), 1)
    if 'array' in type_ and 'uniqueItems' in schema and isinstance(schema.get('items', []), dict):
        item_count = upper_bound_instances(schema['items'])
        if math.isfinite(item_count):
            schema['maxItems'] = min(item_count, schema.get('maxItems', math.inf))
    if 'array' in type_ and schema.get('minItems', 0) > schema.get('maxItems', math.inf):
        type_.remove('array')
    if 'array' in type_ and 'minItems' in schema and isinstance(schema.get('items', []), dict):
        count = upper_bound_instances(schema['items'])
        if count == 0 and schema['minItems'] > 0 or (schema.get('uniqueItems', False) and count < schema['minItems']):
            type_.remove('array')
    if 'array' in type_ and isinstance(schema.get('items'), list):
        schema['items'] = schema['items'][:schema.get('maxItems')]
        for idx, s in enumerate(schema['items']):
            if s == FALSEY:
                schema['items'] = schema['items'][:idx]
                schema['maxItems'] = idx
                schema.pop('additionalItems', None)
                break
        if schema.get('minItems', 0) > min(len(schema['items']) + upper_bound_instances(schema.get('additionalItems', TRUTHY)), schema.get('maxItems', math.inf)):
            type_.remove('array')
    if 'array' in type_ and isinstance(schema.get('items'), list) and (schema.get('additionalItems') == FALSEY):
        schema.pop('maxItems', None)
    if 'array' in type_ and (schema.get('items') == FALSEY or schema.get('maxItems', 1) == 0):
        schema['maxItems'] = 0
        schema.pop('items', None)
        schema.pop('uniqueItems', None)
        schema.pop('additionalItems', None)
    if 'array' in type_ and schema.get('items', TRUTHY) == TRUTHY:
        schema.pop('items', None)
    if 'properties' in schema and (not schema.get('patternProperties')) and (schema.get('additionalProperties') == FALSEY):
        max_props = schema.get('maxProperties', math.inf)
        assert isinstance(max_props, (int, float))
        for k, v in list(schema['properties'].items()):
            if v == FALSEY:
                schema['properties'].pop(k)
        schema['maxProperties'] = min(max_props, len(schema['properties']))
    if schema.get('maxProperties', math.inf) == 0:
        for k in ('properties', 'patternProperties', 'additionalProperties'):
            schema.pop(k, None)
    if 'object' in type_ and schema.get('minProperties', 0) > schema.get('maxProperties', math.inf):
        type_.remove('object')
    for k, v in schema.get('dependencies', {}).copy().items():
        if v in ([], TRUTHY):
            schema['dependencies'].pop(k)
    for kw, identity in {'minItems': 0, 'items': {}, 'additionalItems': {}, 'dependencies': {}, 'minProperties': 0, 'properties': {}, 'propertyNames': {}, 'patternProperties': {}, 'additionalProperties': {}, 'required': []}.items():
        if kw in schema and schema[kw] == identity:
            schema.pop(kw)
    if 'object' in type_ and 'required' in schema:
        assert isinstance(schema['required'], list)
        reqs = set(schema['required'])
        if schema.get('dependencies'):
            dep_names = {k: sorted(set(v)) for k, v in schema['dependencies'].items() if isinstance(v, list)}
            schema['dependencies'].update(dep_names)
            while reqs.intersection(dep_names):
                for r in reqs.intersection(dep_names):
                    reqs.update(dep_names.pop(r))
                    schema['dependencies'].pop(r)
            if not schema['dependencies']:
                schema.pop('dependencies')
        schema['required'] = sorted(reqs)
        max_ = schema.get('maxProperties', float('inf'))
        assert isinstance(max_, (int, float))
        properties = schema.get('properties', {})
        propnames_validator = make_validator(schema.get('propertyNames', {})).is_valid
        if len(schema['required']) > max_ or any((properties.get(name, {}) == FALSEY for name in schema['required'])) or (not all((propnames_validator(name) for name in schema['required']))):
            type_.remove('object')
    for t, kw in TYPE_SPECIFIC_KEYS:
        numeric = {'number', 'integer'}
        if t in type_ or (t in numeric and numeric.intersection(type_)):
            continue
        for k in kw.split():
            schema.pop(k, None)
    if 'not' in schema:
        not_ = schema.pop('not')
        negated = []
        to_negate = not_['anyOf'] if set(not_) == {'anyOf'} else [not_]
        for not_ in to_negate:
            type_keys = {k: set(v.split()) for k, v in TYPE_SPECIFIC_KEYS}
            type_constraints = {'type'}
            for v in type_keys.values():
                type_constraints |= v
            if set(not_).issubset(type_constraints):
                not_['type'] = get_type(not_)
                for t in set(type_).intersection(not_['type']):
                    if not type_keys.get(t, set()).intersection(not_):
                        type_.remove(t)
                        if t not in ('integer', 'number'):
                            not_['type'].remove(t)
                not_ = canonicalish(not_)
            m = merged([not_, {**schema, 'type': type_}])
            if m is not None:
                not_ = m
            if not_ != FALSEY:
                negated.append(not_)
        if len(negated) > 1:
            schema['not'] = {'anyOf': negated}
        elif negated:
            schema['not'] = negated[0]
    assert isinstance(type_, list), type_
    if not type_:
        assert type_ == []
        return FALSEY
    if type_ == ['null']:
        return {'const': None}
    if type_ == ['boolean']:
        return {'enum': [False, True]}
    if type_ == ['null', 'boolean']:
        return {'enum': [None, False, True]}
    if len(type_) == 1:
        schema['type'] = type_[0]
    elif type_ == get_type({}):
        schema.pop('type', None)
    else:
        schema['type'] = type_
    if TRUTHY in schema.get('anyOf', ()):
        schema.pop('anyOf', None)
    if 'anyOf' in schema:
        i = 0
        while i < len(schema['anyOf']):
            s = schema['anyOf'][i]
            if set(s) == {'anyOf'}:
                schema['anyOf'][i:i + 1] = s['anyOf']
                continue
            i += 1
        schema['anyOf'] = [json.loads(s) for s in sorted({encode_canonical_json(a) for a in schema['anyOf'] if a != FALSEY})]
        if not schema['anyOf']:
            return FALSEY
        if len(schema) == len(schema['anyOf']) == 1:
            return schema['anyOf'][0]
        types = []
        for subschema in schema['anyOf']:
            if 'type' in subschema and len(subschema) == 1:
                types.extend(get_type(subschema))
            else:
                break
        else:
            del schema['anyOf']
            new_types = canonicalish({'type': types})
            schema = merged([schema, new_types])
            assert isinstance(schema, dict)
    if 'allOf' in schema:
        schema['allOf'] = [json.loads(enc) for enc in sorted(set(map(encode_canonical_json, schema['allOf'])))]
        if any((s == FALSEY for s in schema['allOf'])):
            return FALSEY
        if all((s == TRUTHY for s in schema['allOf'])):
            schema.pop('allOf')
        elif len(schema) == len(schema['allOf']) == 1:
            return schema['allOf'][0]
        else:
            tmp = schema.copy()
            ao = tmp.pop('allOf')
            out = merged([tmp, *ao])
            if out is not None:
                schema = out
    if 'oneOf' in schema:
        one_of = schema.pop('oneOf')
        assert isinstance(one_of, list)
        one_of = sorted(one_of, key=encode_canonical_json)
        one_of = [s for s in one_of if s != FALSEY]
        if len(one_of) == 1:
            m = merged([schema, one_of[0]])
            if m is not None:
                return m
        if not one_of or one_of.count(TRUTHY) > 1:
            return FALSEY
        schema['oneOf'] = one_of
    if schema.get('uniqueItems') is False:
        del schema['uniqueItems']
    return schema

def from_schema(schema: Union[bool, Schema], *, custom_formats: Optional[Dict[str, st.SearchStrategy[str]]]=None, allow_x00: bool=True, codec: Optional[str]='utf-8') -> st.SearchStrategy[JSONType]:
    """Take a JSON schema and return a strategy for allowed JSON objects.

    To generate specific string formats, pass a ``custom_formats`` dict
    mapping the format name to a strategy for allowed strings.

    You can constrain strings _other than those from custom format strategies_
    by passing ``allow_x00=False`` to exclude the null character ``chr(0)``,
