def upper_bound_instances(schema: Schema) -> float:
    """Return an upper bound on the number of instances that match this schema."""
    if schema == FALSEY:
        return 0
    if 'const' in schema:
        return 1
    if 'enum' in schema:
        assert isinstance(schema['enum'], list)
