def resolve_all_refs(schema: Union[bool, Schema], *, resolver: Optional[LocalResolver]=None) -> Schema:
    """
    Resolve all references in the given schema.

    This handles nested definitions, but not recursive definitions.
    The latter require special handling to convert to strategies and are much
    less common, so we just ignore them (and error out) for now.
    """
    if isinstance(schema, bool):
        return canonicalish(schema)
    assert isinstance(schema, dict), schema
    if resolver is None:
        resolver = LocalResolver.from_schema(deepcopy(schema))
    if not isinstance(resolver, _RefResolver):
        raise InvalidArgument(f'resolver={resolver} (type {type(resolver).__name__}) is not a RefResolver')
    if '$ref' in schema:
        s = dict(schema)
        ref = s.pop('$ref')
        with resolver.resolving(ref) as got:
            m = merged([s, resolve_all_refs(got, resolver=resolver)])
            if m is None:
                msg = f'$ref:{ref!r} had incompatible base schema {s!r}'
                raise HypothesisRefResolutionError(msg)
            assert '$ref' not in m
            return m
    assert '$ref' not in schema
    for key in SCHEMA_KEYS:
        val = schema.get(key, False)
        if isinstance(val, list):
            schema[key] = [resolve_all_refs(v, resolver=resolver) if isinstance(v, dict) else v for v in val]
        elif isinstance(val, dict):
            schema[key] = resolve_all_refs(val, resolver=resolver)
        else:
            assert isinstance(val, bool)
    for key in SCHEMA_OBJECT_KEYS:
        if key in schema:
            subschema = schema[key]
            assert isinstance(subschema, dict)
            schema[key] = {k: resolve_all_refs(v, resolver=resolver) if isinstance(v, dict) else v for k, v in subschema.items()}
    assert isinstance(schema, dict)
    assert '$ref' not in schema
    return schema

def from_schema(schema: Union[bool, Schema], *, custom_formats: Optional[Dict[str, st.SearchStrategy[str]]]=None, allow_x00: bool=True, codec: Optional[str]='utf-8') -> st.SearchStrategy[JSONType]:
    """Take a JSON schema and return a strategy for allowed JSON objects.

    To generate specific string formats, pass a ``custom_formats`` dict
    mapping the format name to a strategy for allowed strings.

    You can constrain strings _other than those from custom format strategies_
    by passing ``allow_x00=False`` to exclude the null character ``chr(0)``,
    and/or a ``codec=`` name such as ``"utf-8"``, ``"ascii"``, or any other
    text encoding supported by Python.

    Supports JSONSchema drafts 04, 06, and 07, with the exception of
    recursive references.
    """
    try:
        return __from_schema(deepcopy(schema), custom_formats=custom_formats, alphabet=CharStrategy.from_args(allow_x00=allow_x00, codec=codec))
    except Exception as err:
        error = err

        def error_raiser() -> NoReturn:
            raise error
        return st.builds(error_raiser)

