                out['additionalItems'] = merged([out.get('additionalItems', TRUTHY), sitems])
            elif isinstance(sitems, list):
                out['items'] = [merged([x, oitems]) for x in sitems]
                out['additionalItems'] = merged([s.get('additionalItems', TRUTHY), oitems])
