                out['items'] = merged([oitems, sitems])
                if out['items'] is None:
                    return None
            if isinstance(out['items'], list) and None in out['items']:
                return None
            if out.get('additionalItems', TRUTHY) is None:
                return None
            s.pop('additionalItems', None)
