        return (string_timestamp(h2, m2, s2, ms2, ts2paddings), string_timestamp(h1, m1, s1, ms1, ts1paddings))
    return st.builds(get_equiv_timestamps, maybe_off_by_one_fields(), maybe_off_by_one_fields(), maybe_off_by_one_fields(), ts_field_value(), st.tuples(*[zero_padding() for _ in range(4)]), st.tuples(*[zero_padding() for _ in range(4)]))

