            actual_types.append(attr_type)
            attrs_dict[attr_name] = typevar
    cls = make_typeddict('HypTypedDict', attrs_dict, total=total, bases=[Generic[tuple(generics)]])
    if draw(booleans()):

        class InheritedTypedDict(cls[tuple(actual_types)]):
