            success_payload[n] = v
    cls = ((TypedDict if draw(booleans()) else ExtensionsTypedDict) if typeddict_cls is None else typeddict_cls)('HypTypedDict', attrs_dict, total=total)
    note('\n'.join([f'class HypTypedDict(TypedDict{('' if total else ', total=False')}):', *[f'    {n}: {a}' for n, a in attrs_dict.items()]]))
    if draw(booleans()):

