        res = any_typed_attrs(defaults, kw_only) | int_typed_attrs(defaults, kw_only) | str_typed_attrs(defaults, kw_only, text_codec) | float_typed_attrs(defaults, kw_only, allow_infinity, allow_nan) | frozenset_typed_attrs(defaults, legacy_types_only=True, kw_only=kw_only) | homo_tuple_typed_attrs(defaults, legacy_types_only=True, kw_only=kw_only) | path_typed_attrs(defaults, kw_only=kw_only)
