def make_dict_unstructure_fn(cl: type[T], converter: BaseConverter, _cattrs_use_linecache: bool=True, **kwargs: AttributeOverride) -> Callable[[T], dict[str, Any]]:
    """
    Generate a specialized dict unstructuring function for a TypedDict.

    :param cl: A `TypedDict` class.
    :param converter: A Converter instance to use for unstructuring nested fields.
    :param kwargs: A mapping of field names to an `AttributeOverride`, for
        customization.
    :param _cattrs_detailed_validation: Whether to store the generated code in the
        _linecache_, for easier debugging and better stack traces.
    """
    origin = get_origin(cl)
    attrs = _adapted_fields(origin or cl)
    req_keys = _required_keys(origin or cl)
    mapping = {}
    if is_generic(cl):
        mapping = generate_mapping(cl, mapping)
        for base in getattr(origin, '__orig_bases__', ()):
            if is_generic(base) and (not str(base).startswith('typing.Generic')):
                mapping = generate_mapping(base, mapping)
                break
        if origin is not None:
            cl = origin
    cl_name = cl.__name__
    fn_name = 'unstructure_typeddict_' + cl_name
    globs = {}
    lines = []
    internal_arg_parts = {}
    try:
        working_set = already_generating.working_set
    except AttributeError:
        working_set = set()
        already_generating.working_set = working_set
    if cl in working_set:
        raise RecursionError()
    working_set.add(cl)
    try:
        for a in attrs:
            attr_name = a.name
            override = kwargs.get(attr_name, neutral)
            if override != neutral:
                break
            handler = None
            t = a.type
            if isinstance(t, TypeVar):
                if t.__name__ in mapping:
                    t = mapping[t.__name__]
                else:
                    handler = converter.unstructure
            elif is_generic(t) and (not is_bare(t)) and (not is_annotated(t)):
                t = deep_copy_with(t, mapping)
            if handler is None:
                nrb = get_notrequired_base(t)
                if nrb is not NOTHING:
                    t = nrb
                try:
                    handler = converter.get_unstructure_hook(t)
                except RecursionError:
                    handler = converter.unstructure
            is_identity = handler == identity
            if not is_identity:
                break
        else:
            return identity
        for ix, a in enumerate(attrs):
            attr_name = a.name
            override = kwargs.get(attr_name, neutral)
            if override.omit:
                lines.append(f"  res.pop('{attr_name}', None)")
                continue
            if override.rename is not None:
                lines.append(f"  res.pop('{attr_name}', None)")
            kn = attr_name if override.rename is None else override.rename
            attr_required = attr_name in req_keys
            handler = None
            if override.unstruct_hook is not None:
                handler = override.unstruct_hook
            else:
                t = a.type
                if isinstance(t, TypeVar):
                    if t.__name__ in mapping:
                        t = mapping[t.__name__]
                    else:
                        handler = converter.unstructure
                elif is_generic(t) and (not is_bare(t)) and (not is_annotated(t)):
                    t = deep_copy_with(t, mapping)
                if handler is None:
                    nrb = get_notrequired_base(t)
                    if nrb is not NOTHING:
                        t = nrb
                    try:
                        handler = converter.get_unstructure_hook(t)
                    except RecursionError:
                        handler = converter.unstructure
            is_identity = handler == identity
            if not is_identity:
                unstruct_handler_name = f'__c_unstr_{ix}'
                globs[unstruct_handler_name] = handler
                internal_arg_parts[unstruct_handler_name] = handler
                invoke = f"{unstruct_handler_name}(instance['{attr_name}'])"
            elif override.rename is None:
                continue
            else:
                invoke = f"instance['{attr_name}']"
            if attr_required:
                lines.append(f"  res['{kn}'] = {invoke}")
            else:
                lines.append(f"  if '{attr_name}' in instance: res['{kn}'] = {invoke}")
        internal_arg_line = ', '.join([f'{i}={i}' for i in internal_arg_parts])
        if internal_arg_line:
            internal_arg_line = f', {internal_arg_line}'
        for k, v in internal_arg_parts.items():
            globs[k] = v
        total_lines = [f'def {fn_name}(instance{internal_arg_line}):', '  res = instance.copy()', *lines, '  return res']
        script = '\n'.join(total_lines)
        fname = generate_unique_filename(cl, 'unstructure', lines=total_lines if _cattrs_use_linecache else [])
        eval(compile(script, fname, 'exec'), globs)
    finally:
        working_set.remove(cl)
        if not working_set:
            del already_generating.working_set
    return globs[fn_name]

def _create_hyp_class(attrs_and_strategy: List[Tuple[_CountingAttr, st.SearchStrategy[PosArgs]]], frozen=None):
    """
    A helper function for Hypothesis to generate attrs classes.

    The result is a tuple: an attrs class, a tuple of values to
    instantiate it, and a kwargs dict for kw-only attributes.
    """

    def key(t):
        return (t[0].default is not NOTHING, t[0].kw_only)
    attrs_and_strat = sorted(attrs_and_strategy, key=key)
    attrs = [a[0] for a in attrs_and_strat]
    for i, a in enumerate(attrs):
        a.counter = i
    vals = tuple((a[1] for a in attrs_and_strat if not a[0].kw_only))
    kwargs = {}
    for attr_name, attr_and_strat in zip(gen_attr_names(), attrs_and_strat):
        if attr_and_strat[0].kw_only:
            if attr_name.startswith('_'):
                attr_name = attr_name[1:]
            kwargs[attr_name] = attr_and_strat[1]
    return st.tuples(st.builds(lambda f: make_class('HypClass', OrderedDict(zip(gen_attr_names(), attrs)), frozen=f), st.booleans() if frozen is None else st.just(frozen)), st.tuples(*vals), st.fixed_dictionaries(kwargs))

def adapted_fields(cl) -> List[Attribute]:
    """Return the attrs format of `fields()` for attrs and dataclasses."""
    if is_dataclass(cl):
        attrs = dataclass_fields(cl)
        if any((isinstance(a.type, str) for a in attrs)):
            type_hints = get_type_hints(cl)
        else:
            type_hints = {}
        return [Attribute(attr.name, attr.default if attr.default is not MISSING else Factory(attr.default_factory) if attr.default_factory is not MISSING else NOTHING, None, True, None, True, attr.init, True, type=type_hints.get(attr.name, attr.type), alias=attr.name) for attr in attrs]
    attribs = attrs_fields(cl)
    if any((isinstance(a.type, str) for a in attribs)):
        resolve_types(cl)
        attribs = attrs_fields(cl)
    return attribs

