    if supertype is not None and getattr(typ, '__qualname__', '') == 'NewType.<locals>.new_type' and (typ.__module__ in ('typing', 'typing_extensions')):
        return supertype
    return None

def configure_union_passthrough(union: Any, converter: BaseConverter) -> None:
    """
    Configure the converter to support validating and passing through unions of the
    provided types and their subsets.

    For example, all mature JSON libraries natively support producing unions of ints,
    floats, Nones, and strings. Using this strategy, a converter can be configured
    to efficiently validate and pass through unions containing these types.

    The most important point is that another library (in this example the JSON
    library) handles producing the union, and the converter is configured to just
    validate it.

    Literals of provided types are also supported, and are checked by value.

    NewTypes of provided types are also supported.

    The strategy is designed to be O(1) in execution time, and independent of the
    ordering of types in the union.

    If the union contains a class and one or more of its subclasses, the subclasses
    will also be included when validating the superclass.

    .. versionadded:: 23.2.0
    """
    args = set(union.__args__)

    def make_structure_native_union(exact_type: Any) -> Callable:
        literal_values = {v for t in exact_type.__args__ if is_literal(t) for v in t.__args__}
        literal_classes = {v.__class__ for t in exact_type.__args__ if is_literal(t) for v in t.__args__}
        non_literal_classes = {get_newtype_base(t) or t for t in exact_type.__args__ if not is_literal(t) and (get_newtype_base(t) or t) in args}
        non_literal_classes |= {a for a in args if any((is_subclass(a, c) for c in non_literal_classes))}
        spillover = {a for a in exact_type.__args__ if (get_newtype_base(a) or a) not in non_literal_classes and (not is_literal(a))}
        if spillover:
            spillover_type = Union[tuple(spillover)] if len(spillover) > 1 else next(iter(spillover))

            def structure_native_union(val: Any, _: Any, classes=non_literal_classes, vals=literal_values, converter=converter, spillover=spillover_type) -> exact_type:
                if val.__class__ in literal_classes and val in vals:
                    return val
                if val.__class__ in classes:
                    return val
                return converter.structure(val, spillover)
        else:

            def structure_native_union(val: Any, _: Any, classes=non_literal_classes, vals=literal_values) -> exact_type:
                if val.__class__ in literal_classes and val in vals:
                    return val
                if val.__class__ in classes:
                    return val
                raise TypeError(f'{val} ({val.__class__}) not part of {_}')
        return structure_native_union

    def contains_native_union(exact_type: Any) -> bool:
        """Can we handle this type?"""
        if is_union_type(exact_type):
            type_args = set(exact_type.__args__)
            if len(type_args) == 2 and type(None) in type_args:
                return False
            literal_classes = {lit_arg.__class__ for t in type_args if is_literal(t) for lit_arg in t.__args__}
            non_literal_types = {get_newtype_base(t) or t for t in type_args if not is_literal(t)}
            return (literal_classes | non_literal_types) & args
        return False
    converter.register_structure_hook_factory(contains_native_union, make_structure_native_union)

