def get_annot(t) -> dict:
    """Our version, handling type vars properly."""
    if is_generic(t):
        origin = getattr(t, '__origin__', None)
        if origin is not None:
            origin_annotations = get_annots(origin)
            args = t.__args__
            params = origin.__parameters__
            param_to_args = dict(zip(params, args))
            res = {}
            for k, v in origin_annotations.items():
                if (nrb := get_notrequired_base(v)) is not NOTHING:
                    res[k] = NotRequired[param_to_args[nrb]] if nrb in param_to_args else v
                else:
                    res[k] = param_to_args[v] if v in param_to_args else v
            return res
        mapping = generate_mapping(t)
        res = {}
        for k, v in get_annots(t).items():
            if (nrb := get_notrequired_base(v)) is not NOTHING:
                res[k] = NotRequired[mapping[nrb.__name__]] if nrb.__name__ in mapping else v
            else:
                res[k] = mapping[v.__name__] if v.__name__ in mapping else v
        return res
    return get_annots(t)

def generate_mapping(cl: type, old_mapping: dict[str, type]={}) -> dict[str, type]:
    """Generate a mapping of typevars to actual types for a generic class."""
    mapping = dict(old_mapping)
    origin = get_origin(cl)
    if origin is not None:
        parameters = getattr(get_origin(cl), '__parameters__', None)
        if parameters is None:
            return dict(old_mapping)
        for p, t in zip(parameters, get_args(cl)):
            if isinstance(t, TypeVar):
                continue
            mapping[p.__name__] = t
    elif is_generic(cl):
        orig_bases = cl.__orig_bases__
        for base in orig_bases:
            if not hasattr(base, '__args__'):
                continue
            base_args = base.__args__
            if hasattr(base.__origin__, '__parameters__'):
                base_params = base.__origin__.__parameters__
            elif any((_tvar_has_default(base_arg) for base_arg in base_args)):
                mapping_params = [(base_arg, base_arg.__default__) for base_arg in base_args if _tvar_has_default(base_arg)]
                base_params, base_args = zip(*mapping_params)
            else:
                continue
            for param, arg in zip(base_params, base_args):
                mapping[param.__name__] = arg
    return mapping

