def get_sampler_servers(local_stub=None):
    """Parses the config file (or the fallback at the checked in location)
    to get a list of connection strings, and to determine whether local
    parallel evaluation is enabled.

    Returns a list of stubs for each configured connection, including
    local_stub`, the local parallel evaluation object, if provided
    and local parallelism is enabled (not explicitly disabled).

    As a second value, returns whether inline (single-threaded)
    evaluation is enabled.
    """
    ret = []
    if 'pytest' in sys.modules:
        return ([local_stub] if local_stub is not None else [], True)
    servers, use_local, inline_eval = parse_sampler_servers()
    if not servers:
        servers, use_local, inline_eval = parse_sampler_servers(SECONDARY_CONFIG_PATH)
    if use_local and local_stub is not None:
        ret.append(local_stub)
    for name, connection_string in servers:
        try:
            channel = grpc.insecure_channel(connection_string)
            stub = ExactTestSamplerStub(channel)
            status = stub.status(StatusRequest(), timeout=CONNECTION_TIMEOUT)
            print('Succesfully connected to %s @ %s (status=%s).' % (name, connection_string, status), file=sys.stderr)
            ret.append(stub)
        except Exception as e:
            print('Unabled to open connection %s to %s: %s.' % (name, connection_string, e), file=sys.stderr)
    return (ret, inline_eval)

def parse_sampler_servers(path=CONFIG_PATH):
    config = configparser.ConfigParser()
    ret = []
    use_local = True
    inline_eval = True
    try:
        config.read(path)
        use_local = config.getboolean('local_sampler_executor', 'local_parallelism', fallback=True)
        inline_eval = config.getboolean('local_sampler_executor', 'inline_evaluation', fallback=True)
        for host in config:
            if host == 'DEFAULT':
                continue
            if host == 'local_sampler_executor':
                continue
            hostname = config.get(host, 'hostname', fallback=host)
            ret.append((host, hostname + ':' + config.get(host, 'port')))
    except FileNotFoundError:
        pass
    return (ret, use_local, inline_eval)

def exact_test(a, b, statistics, eps=0.0001, log=sys.stderr):
    """Performs an exact significance test for every statistic in
    `statistics`, on u63-valued observations in a and b, with false
    positive rate eps.

    Returns a dict of results.  For each statistic, the result will
    have one entry mapping the statistic's name to a Result.
    """
    if not statistics:
        return dict()
    if len(statistics) != len({stat.name for stat in statistics}):
        raise Exception("Statistics' names must be unique.")
    actual_data = Sample(a, b)
    num_stats = len(statistics)
    eps /= 2 * num_stats * 1.1
    log_inner_eps = math.log(eps / 10)
    actual_stats = actual_data_results(actual_data, statistics)
    if log:
        print('actual: %s' % actual_stats, file=log)
    accumulators = {name: INITIAL_RESULT_ACCUMULATOR for name in actual_stats}
    ret = dict()
    for name, actual in actual_stats.items():
        if actual != actual or (not actual_data.a_class and (not actual_data.b_class)):
            ret[name] = Result(actual, 0, len(actual_data.a_class), len(actual_data.b_class), 0)
    if len(ret) == len(actual_stats):
        return ret
    grouped_stats_queue = queue.SimpleQueue()

    def update_grouped_stats():
        grouped_stats_queue.put(_group_statistics_in_plan([stat for stat in statistics if stat.name not in ret]))
    begin = time.monotonic()
    seen = 0
    test_every = 250
    update_grouped_stats()
    eval_period_begin = time.monotonic()
    eval_period_seen = 0
    for sample in resampled_data_results(actual_data, grouped_stats_queue):
        for name, stat in sample.items():
            actual = actual_stats[name]
            current = accumulators[name]
            if stat <= actual:
                current = current._replace(lte_actual=current.lte_actual + 1)
            if stat >= actual:
                current = current._replace(gte_actual=current.gte_actual + 1)
            accumulators[name] = current._replace(trials=current.trials + 1)
        seen += 1
        if seen % test_every != 0:
            continue
        if seen >= 40 * test_every:
            test_every *= 10
        if log is not None:
            now = time.monotonic()
            print('%i\tElapsed: %f\t(%f eval/s)' % (seen, now - begin, (seen - eval_period_seen) / (1e-08 + now - eval_period_begin)), file=log)
            eval_period_begin = now
            eval_period_seen = seen
        new_significant = False
        for name, acc in accumulators.items():
            if name in ret:
                continue
            if _significance_test(ret, eps, log_inner_eps, name, sample[name], actual_data, actual_stats[name], acc.lte_actual, acc.gte_actual, acc.trials, log):
                new_significant = True
        if new_significant:
            update_grouped_stats()
        if len(ret) == len(actual_stats):
            return {name: ret[name] for name in actual_stats}

