    s = binascii.unhexlify(s)
    llen = len(s)
    return int2byte(128 | llen) + s

def encode_number(n):
    b128_digits = []
    while n:
        b128_digits.insert(0, n & 127 | 128)
        n = n >> 7
    if not b128_digits:
        b128_digits.append(0)
    b128_digits[-1] &= 127
    return b''.join([int2byte(d) for d in b128_digits])

